	"github.com/cocosolocoder/signalroom/internal/events"
)

// sampleDTO is the on-disk representation of a normalized sample. Timestamps
// use RFC3339Nano; Labels is omitted entirely when a sample has none.
type sampleDTO struct {
	ID      string            `json:"id"`
	Service string            `json:"service"`
	Name    string            `json:"name"`
	At      time.Time         `json:"at"`
	Value   float64           `json:"value"`
	Labels  map[string]string `json:"labels,omitempty"`
}

// allowedSampleFields is the exact set of members one sample may carry.
var allowedSampleFields = map[string]struct{}{
	"id":      {},
	"service": {},
	"name":    {},
	"at":      {},
	"value":   {},
	"labels":  {},
}

// rawSample keeps the labels member unexamined so the same strict,
// duplicate-rejecting object decoder events use can validate it.
type rawSample struct {
	id      string
	service string
	name    string
	at      time.Time
	value   float64
	labels  map[string]string
}

// MarshalBatch encodes normalized samples as a JSON array.
func MarshalBatch(batch []Sample) ([]byte, error) {
	dtos := make([]sampleDTO, len(batch))
	for i, sample := range batch {
		dtos[i] = sampleDTO{
			ID:      sample.ID,
			Service: sample.Service,
			Name:    sample.Name,
			At:      sample.At,
			Value:   sample.Value,
			Labels:  sample.Labels,
		}
	}
	return json.Marshal(dtos)
}

// DecodeBatch strictly decodes a JSON array of samples. Unknown fields,
// duplicate JSON members (at the sample level or inside labels), syntax
// errors, malformed timestamps, non-numeric or non-finite values, malformed
// labels, and trailing data are all rejected; callers remain responsible for
// the empty-array check and content validation.
func DecodeBatch(data []byte) ([]Sample, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	open, err := dec.Token()
	if err != nil {
		return nil, fmt.Errorf("decode samples array: %w", err)
	}
	if delim, ok := open.(json.Delim); !ok || delim != '[' {
		return nil, fmt.Errorf("decode samples array: must be an array")
	}

	var batch []Sample
	for dec.More() {
		raw, err := decodeSample(dec)
		if err != nil {
			return nil, err
		}
		batch = append(batch, Sample{
			ID:      raw.id,
			Service: raw.service,
			Name:    raw.name,
			At:      raw.at,
			Value:   raw.value,
			Labels:  raw.labels,
		})
	}
	if _, err := dec.Token(); err != nil { // closing ']'
		return nil, fmt.Errorf("decode samples array: %w", err)
	}
	var extra json.RawMessage
	if err := dec.Decode(&extra); err != io.EOF {
		if err == nil {
			return nil, fmt.Errorf("decode samples array: unexpected trailing data")
		}
		return nil, fmt.Errorf("decode samples array: %w", err)
	}
	return batch, nil
}

// decodeSample reads exactly one sample object, rejecting unknown and
// duplicate members rather than letting a struct decode silently keep the
// last value.
func decodeSample(dec *json.Decoder) (rawSample, error) {
	open, err := dec.Token()
	if err != nil {
		return rawSample{}, fmt.Errorf("decode sample: %w", err)
	}
	if delim, ok := open.(json.Delim); !ok || delim != '{' {
		return rawSample{}, fmt.Errorf("decode sample: each sample must be an object")
	}

	var raw rawSample
	var labelsRaw json.RawMessage
	seen := make(map[string]struct{})
	for dec.More() {
		keyToken, err := dec.Token()
		if err != nil {
			return rawSample{}, fmt.Errorf("decode sample: %w", err)
		}
		key, ok := keyToken.(string)
		if !ok {
			return rawSample{}, fmt.Errorf("decode sample: field names must be strings")
		}
		if _, known := allowedSampleFields[key]; !known {
			return rawSample{}, fmt.Errorf("decode sample: unknown field %q", key)
		}
		if _, dup := seen[key]; dup {
			return rawSample{}, fmt.Errorf("decode sample: duplicate field %q", key)
		}
		seen[key] = struct{}{}

		switch key {
		case "id", "service", "name":
			var value string
			if err := dec.Decode(&value); err != nil {
				return rawSample{}, fmt.Errorf("decode sample: %s must be a string", key)
			}
			switch key {
			case "id":
				raw.id = value
			case "service":
				raw.service = value
			case "name":
				raw.name = value
			}
		case "at":
			var at time.Time
			if err := dec.Decode(&at); err != nil {
				return rawSample{}, fmt.Errorf("decode sample: at must be an RFC3339Nano timestamp")
			}
			raw.at = at
		case "value":
			// Decode the raw token first: json.Number has an underlying string
			// type, so a quoted "1" would otherwise decode into it. Require
			// the token to literally be a JSON number before parsing.
			var token json.RawMessage
			if err := dec.Decode(&token); err != nil {
				return rawSample{}, fmt.Errorf("decode sample: value must be a JSON number")
			}
			number := bytes.TrimSpace(token)
			if !isJSONNumber(number) {
				return rawSample{}, fmt.Errorf("decode sample: value must be a non-negative, finite JSON number")
			}
			value, err := json.Number(number).Float64()
			if err != nil || !finiteNonNegative(value) {
				return rawSample{}, fmt.Errorf("decode sample: value must be a non-negative, finite JSON number")
			}
			raw.value = value
		case "labels":
			if err := dec.Decode(&labelsRaw); err != nil {
				return rawSample{}, fmt.Errorf("decode sample: labels must be an object")
			}
		}
	}
	if _, err := dec.Token(); err != nil { // closing '}'
		return rawSample{}, fmt.Errorf("decode sample: %w", err)
	}

	labels, err := events.DecodeLabelsObject(labelsRaw)
	if err != nil {
		return rawSample{}, err
	}
	// value has no useful zero value, so an absent member is an error rather
	// than a silent 0; id/service/name/at are caught by later normalization.
	if _, ok := seen["value"]; !ok {
		return rawSample{}, fmt.Errorf("decode sample: value is required")
	}
	raw.labels = labels
	return raw, nil
}

// isJSONNumber validates the strict JSON number grammar, so a quoted string,
// NaN, or Infinity never reach the float parser.
func isJSONNumber(b []byte) bool {
	i := 0
	if i < len(b) && b[i] == '-' {
		i++
	}
	if i >= len(b) {
		return false
	}
	if b[i] == '0' {
		i++
	} else if b[i] >= '1' && b[i] <= '9' {
		i++
		for i < len(b) && b[i] >= '0' && b[i] <= '9' {
			i++
		}
	} else {
		return false
	}
	if i < len(b) && b[i] == '.' {
		i++
		if i >= len(b) || b[i] < '0' || b[i] > '9' {
			return false
		}
		for i < len(b) && b[i] >= '0' && b[i] <= '9' {
			i++
		}
	}
	if i < len(b) && (b[i] == 'e' || b[i] == 'E') {
		i++
		if i < len(b) && (b[i] == '+' || b[i] == '-') {
			i++
		}
		if i >= len(b) || b[i] < '0' || b[i] > '9' {
			return false
		}
		for i < len(b) && b[i] >= '0' && b[i] <= '9' {
			i++
		}
	}
	return i == len(b)
}

package logfile

import (
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"os"
	"path/filepath"
	"sync"
)

const (
	headerSize = 8
	// MaxPayloadBytes is the 64 MiB (1024*1024-byte units) capacity of one
	// frame payload. It bounds the saved content itself, excluding the
	// 8-byte frame header, and guards against absurd allocations when a
	// corrupt length prefix happens to point inside the file.
	MaxPayloadBytes = 64 << 20
)

// ErrPayloadTooLarge is returned when a frame's encoded content exceeds
// MaxPayloadBytes. It describes the content, not a storage fault: the check
// runs before anything is written or locked for mutation, the log is not
// poisoned, and later writes keep working without a restart.
var ErrPayloadTooLarge = errors.New("frame payload exceeds the 64 MiB save capacity")

// ErrPoisoned is returned after a write or sync failure. The log refuses all
// further writes until the process is restarted and recovery succeeds.
var ErrPoisoned = errors.New("log is unavailable after a storage failure")

// CorruptionError marks a complete frame that fails its checksum or contains
// illegal data, as opposed to an incomplete trailing frame.
type CorruptionError struct{ Reason string }

func (e *CorruptionError) Error() string { return e.Reason }

func corruption(format string, args ...any) error {
	return &CorruptionError{Reason: fmt.Sprintf(format, args...)}
}

// frameLog is the shared append-only frame writer behind the event, incident,
// and metric logs. It owns the frame layout, torn-tail recovery, and the
// poison-on-failure write path; each concrete log supplies only its own
// payload encoding and content validation, so the durability rule lives in
// exactly one place.
type frameLog struct {
	mu       sync.Mutex
	file     *os.File
	dir      string
	noun     string // the log's name in error messages: "event", "incident", "metrics"
	unit     string // what one frame holds: "batch", "incident record", "metric batch"
	poisoned bool
}

// openFrameLog opens (creating if absent) the named log inside an
// already-locked data directory, replays its frames with decode, and
// truncates at most one incomplete trailing frame. A corrupt frame in the
// middle, or a complete frame whose payload decode rejects, is fatal and
// leaves the file untouched.
func openFrameLog[T any](dir, name, noun, unit string, decode func(payload []byte) (T, error)) (*frameLog, []T, error) {
	path := filepath.Join(dir, name)
	file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
	if err != nil {
		return nil, nil, fmt.Errorf("open %s log: %w", noun, err)
	}

	items, validLen, err := replayFrames(file, noun, decode)
	if err != nil {
		file.Close()
		return nil, nil, err
	}
	if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
		// Drop exactly one incomplete trailing frame; the only mutation
		// recovery performs, fsynced before serving.
		if err := file.Truncate(validLen); err != nil {
			file.Close()
			return nil, nil, fmt.Errorf("truncate incomplete trailing %s frame: %w", noun, err)
		}
		if err := file.Sync(); err != nil {
			file.Close()
			return nil, nil, fmt.Errorf("sync %s log: %w", noun, err)
		}
	}
	// Flush the directory so the log file's own entry is durable, whether it
	// was just created or just truncated.
	if err := syncDir(dir); err != nil {
		file.Close()
		return nil, nil, fmt.Errorf("sync data directory: %w", err)
	}

	return &frameLog{file: file, dir: dir, noun: noun, unit: unit}, items, nil
}

// replayFrames scans the log and returns the decoded frames and the byte
// offset at which the log is known good. A torn trailing frame — a partial
// header, or a header whose payload never fully landed — ends the scan
// without error; any corruption before that offset is fatal.
func replayFrames[T any](file *os.File, noun string, decode func(payload []byte) (T, error)) ([]T, int64, error) {
	data, err := os.ReadFile(file.Name())
	if err != nil {
		return nil, 0, fmt.Errorf("read %s log: %w", noun, err)
	}

	var items []T
	pos := int64(0)
	for pos < int64(len(data)) {
		remaining := int64(len(data)) - pos
		if remaining < headerSize {
			break // torn partial header
		}
		payloadLen := int64(binary.BigEndian.Uint32(data[pos : pos+4]))
		if payloadLen <= 0 || payloadLen > MaxPayloadBytes {
			return nil, 0, corruption("corrupt %s frame header at offset %d", noun, pos)
		}
		frameEnd := pos + headerSize + payloadLen
		if frameEnd > int64(len(data)) {
			break // header landed but its payload did not: torn tail
		}
		payload := data[pos+headerSize : frameEnd]
		wantCRC := binary.BigEndian.Uint32(data[pos+4 : pos+headerSize])
		if crc32.ChecksumIEEE(payload) != wantCRC {
			return nil, 0, corruption("%s checksum mismatch at offset %d", noun, pos)
		}
		item, err := decode(payload)
		if err != nil {
			return nil, 0, corruption("illegal %s frame payload at offset %d: %v", noun, pos, err)
		}
		items = append(items, item)
		pos = frameEnd
	}
	return items, pos, nil
}

// appendFrame durably writes one already-encoded payload: the frame is
// written and fsynced before the call returns. Any write or sync failure
// poisons the log, so this call and every later one fail until restart. A
// payload that fails the size check returns ErrPayloadTooLarge before the
// log is touched and does not poison it.
func (l *frameLog) appendFrame(payload []byte) (err error) {
	if len(payload) > MaxPayloadBytes {
		return fmt.Errorf("%w: %s is %d bytes", ErrPayloadTooLarge, l.unit, len(payload))
	}

	frame := make([]byte, headerSize+len(payload))
	binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
	binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
	copy(frame[headerSize:], payload)

	l.mu.Lock()
	defer l.mu.Unlock()
	if l.poisoned {
		return ErrPoisoned
	}
	defer func() {
		if err != nil {
			l.poisoned = true
		}
	}()

	if _, err = l.file.Write(frame); err != nil {
		return fmt.Errorf("write %s log: %w", l.noun, err)
	}
	if err = l.file.Sync(); err != nil {
		return fmt.Errorf("sync %s log: %w", l.noun, err)
	}
	return nil
}

// Poisoned reports whether the log has suffered an unrecoverable write error.
func (l *frameLog) Poisoned() bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.poisoned
}

// Close releases the log file.
func (l *frameLog) Close() error {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.file.Close()
}

