14	// putFrame writes the shared length-prefixed, CRC-checked frame layout into a
15	// buffer sized for one payload.
16	func putFrame(frame, payload []byte) {
17		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
18		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
19		copy(frame[8:], payload)
20	}
