25		if status >= 400 {
26			t.Fatalf("POST /metrics status %d: %s", status, raw)
27		}
28		var out map[string]int
29		if err := json.Unmarshal(raw, &out); err != nil {
30			t.Fatal(err)
31		}
32		return out
33	}
