55	func TestServeMetricsPersistAcrossKillAndDedupeRetry(t *testing.T) {
56		dataDir := t.TempDir()
57		p := startServer(t, dataDir)
58		if counts := postMetrics(t, p, sampleMetrics); counts["created"] != 2 {
59			t.Fatalf("created=%v", counts)
60		}
61	
62		p.signal(t, syscall.SIGKILL)
63		p.waitExit(t, -1)
64		waitTCPPortClosed(t, p.addr)
65	
66		p2 := startServer(t, dataDir)
67		status, got := metricAggregate(t, p2,
68			"?name=requests&since=2026-10-01T10:00:00Z&until=2026-10-01T10:02:00Z&step=60")
69		if status != http.StatusOK {
70			t.Fatalf("aggregate after restart: %d %v", status, got)
71		}
72		if len(got) != 1 {
73			t.Fatalf("one series: %v", got)
74		}
75		segments := got[0]["segments"].([]any)
76		if segments[0].(map[string]any)["delta"].(float64) != 0 ||
77			segments[1].(map[string]any)["delta"].(float64) != 5 {
78			t.Fatalf("deltas must survive restart: %v", segments)
79		}
80	
81		// The identical batch replays with zero created.
82		if counts := postMetrics(t, p2, sampleMetrics); counts["created"] != 0 || counts["replayed"] != 2 {
83			t.Fatalf("retry after restart: %v", counts)
84		}
85		p2.signal(t, syscall.SIGTERM)
86		p2.waitExit(t, 0)
