103	// windowSampleCount aggregates one query expected to match exactly one series
104	// and returns the number of samples across its segments.
105	func windowSampleCount(t *testing.T, p *serverProc, query string) int {
106		t.Helper()
107		status, series := metricAggregate(t, p, query)
108		if status != http.StatusOK || len(series) != 1 {
109			t.Fatalf("aggregate %s: want one series, got %d %v", query, status, series)
110		}
