119	// TestServeMetricsWideDateSamplesAcceptedAcrossEras is the acceptance
120	// guarantee for sampling-instant identity far outside the years for which
121	// time.Time.UnixNano stays exact. The two instants share one naive UnixNano
122	// value, so they must still be received as two distinct points in either
123	// submission order, survive a timezone-only retry as a replay, and remain
124	// independently queryable; a legal post-2262 date is accepted too.
125	func TestServeMetricsWideDateSamplesAcceptedAcrossEras(t *testing.T) {
126		const (
127			oldAt    = "1600-01-01T00:00:00Z"
128			oldAltTZ = "1600-01-01T08:00:00+08:00" // same absolute instant as oldAt
129			futureAt = "2184-07-20T23:34:33.709551616Z"
130		)
131		oldWindow := "?name=requests&service=gateway&since=1599-12-31T23:59:59Z&until=1600-01-01T00:00:01Z&step=2"
132		futureWindow := "?name=requests&service=gateway&since=2184-07-20T23:34:33Z&until=2184-07-20T23:34:34Z&step=1"
133	
134		for _, reverse := range []bool{false, true} {
135			t.Run("order", func(t *testing.T) {
136				p := startServer(t, t.TempDir())
137				body := `{"samples":[
138					{"id":"era-old","service":"gateway","name":"requests","at":"` + oldAt + `","value":1},
139					{"id":"era-new","service":"gateway","name":"requests","at":"` + futureAt + `","value":2}
140				]}`
141				if reverse {
142					body = `{"samples":[
143						{"id":"era-new","service":"gateway","name":"requests","at":"` + futureAt + `","value":2},
144						{"id":"era-old","service":"gateway","name":"requests","at":"` + oldAt + `","value":1}
145					]}`
146				}
147				if counts := postMetrics(t, p, body); counts["created"] != 2 || counts["replayed"] != 0 {
148					t.Fatalf("distant legal dates must both be new (reverse=%v): %v", reverse, counts)
149				}
150	
151				if count := windowSampleCount(t, p, oldWindow); count != 1 {
152					t.Fatalf("old-era window must contain its one point, got %d (reverse=%v)", count, reverse)
153				}
154				if count := windowSampleCount(t, p, futureWindow); count != 1 {
155					t.Fatalf("future-era window must contain its one point, got %d (reverse=%v)", count, reverse)
156				}
157	
158				// The identical batch retries entirely as replays.
159				if counts := postMetrics(t, p, body); counts["created"] != 0 || counts["replayed"] != 2 {
160					t.Fatalf("identical batch must replay (reverse=%v): %v", reverse, counts)
161				}
162	
163				// Same id, same content, only the timezone spelling differs: one
164				// replay, no added sample.
165				if counts := postMetrics(t, p, `{"samples":[
166					{"id":"era-old","service":"gateway","name":"requests","at":"`+oldAltTZ+`","value":1}
167				]}`); counts["created"] != 0 || counts["replayed"] != 1 {
168					t.Fatalf("timezone-only resubmission must replay one: %v", counts)
169				}
170				if count := windowSampleCount(t, p, oldWindow); count != 1 {
171					t.Fatalf("replay must not increase the old-era count, got %d", count)
172				}
173				if count := windowSampleCount(t, p, futureWindow); count != 1 {
174					t.Fatalf("replay must not increase the future-era count, got %d", count)
175				}
176				p.signal(t, syscall.SIGTERM)
177				p.waitExit(t, 0)
178			})
179		}
180	
181		// A legal date after 2262 is not bounded out and is independently
182		// queryable.
183		p := startServer(t, t.TempDir())
184		if counts := postMetrics(t, p, `{"samples":[
185			{"id":"far","service":"gateway","name":"requests","at":"2300-01-02T03:04:05.678901234Z","value":7}
186		]}`); counts["created"] != 1 || counts["replayed"] != 0 {
187			t.Fatalf("post-2262 date must be new: %v", counts)
188		}
189		farWindow := "?name=requests&service=gateway&since=2300-01-02T03:04:05Z&until=2300-01-02T03:04:06Z&step=1"
190		if count := windowSampleCount(t, p, farWindow); count != 1 {
191			t.Fatalf("post-2262 point must be queryable, got %d", count)
192		}
193		p.signal(t, syscall.SIGTERM)
194		p.waitExit(t, 0)
195	}
