197	// TestServeMetricsWideDateConflictsRejectWholeBatch covers the clash rules at
198	// distant dates: another timezone spelling is the same sampling point, a
199	// different id cannot occupy it either against stored data or inside one
200	// batch, mixed batches roll back completely, and the legal sample from a
201	// rejected batch still ingests when sent alone.
202	func TestServeMetricsWideDateConflictsRejectWholeBatch(t *testing.T) {
203		const (
204			oldAt        = "1600-01-01T00:00:00Z"
205			oldAltTZ     = "1600-01-01T08:00:00+08:00"
206			futureAt     = "2184-07-20T23:34:33.709551616Z"
207			futureAltTZ  = "2184-07-20T16:34:33.709551616-07:00" // same instant as futureAt
208			futureNextNS = "2184-07-20T23:34:33.709551617Z"      // one nanosecond later
209		)
210		oldWindow := "?name=requests&service=gateway&since=1599-12-31T23:59:59Z&until=1600-01-01T00:00:01Z&step=2"
211		futureWindow := "?name=requests&service=gateway&since=2184-07-20T23:34:33Z&until=2184-07-20T23:34:34Z&step=1"
212	
213		p := startServer(t, t.TempDir())
214		if counts := postMetrics(t, p, `{"samples":[
215			{"id":"owner","service":"gateway","name":"requests","at":"`+oldAt+`","value":1}
216		]}`); counts["created"] != 1 {
217			t.Fatalf("seed: %v", counts)
218		}
219	
220		// Clash with an already-accepted point via another timezone spelling.
221		postMetricsExpectError(t, p, http.StatusConflict, `{"samples":[
222			{"id":"intruder","service":"gateway","name":"requests","at":"`+oldAltTZ+`","value":5}
223		]}`)
224	
225		// Same absolute future instant under two offsets inside one batch.
226		postMetricsExpectError(t, p, http.StatusConflict, `{"samples":[
227			{"id":"f1","service":"gateway","name":"requests","at":"`+futureAt+`","value":1},
228			{"id":"f2","service":"gateway","name":"requests","at":"`+futureAltTZ+`","value":2}
229		]}`)
230	
231		// One conflicting sample plus one legal new sample: the whole batch is
232		// refused, with nothing left behind.
233		postMetricsExpectError(t, p, http.StatusConflict, `{"samples":[
234			{"id":"intruder2","service":"gateway","name":"requests","at":"`+oldAltTZ+`","value":9},
235			{"id":"fresh","service":"gateway","name":"requests","at":"`+futureNextNS+`","value":3}
236		]}`)
237		if count := windowSampleCount(t, p, oldWindow); count != 1 {
238			t.Fatalf("rollback must leave the old era unchanged, got %d", count)
239		}
240		if status, series := metricAggregate(t, p, futureWindow); status != http.StatusOK || len(series) != 0 {
241			t.Fatalf("legal sample must not survive the rollback, got %d %v", status, series)
242		}
243	
244		// The legal new sample sent on its own really is new.
245		if counts := postMetrics(t, p, `{"samples":[
246			{"id":"fresh","service":"gateway","name":"requests","at":"`+futureNextNS+`","value":3}
247		]}`); counts["created"] != 1 || counts["replayed"] != 0 {
248			t.Fatalf("standalone legal sample must create one: %v", counts)
249		}
250		if count := windowSampleCount(t, p, futureWindow); count != 1 {
251			t.Fatalf("future era must hold the separately ingested point, got %d", count)
252		}
253		if count := windowSampleCount(t, p, oldWindow); count != 1 {
254			t.Fatalf("old era must remain at one point, got %d", count)
255		}
256	
257		// Same id with the instant really moved by one nanosecond is a conflict,
258		// not a replay.
259		postMetricsExpectError(t, p, http.StatusConflict, `{"samples":[
260			{"id":"fresh","service":"gateway","name":"requests","at":"2184-07-20T23:34:33.709551618Z","value":3}
261		]}`)
262		if count := windowSampleCount(t, p, futureWindow); count != 1 {
263			t.Fatalf("failed one-nanosecond move must not add a point, got %d", count)
264		}
265	
266		p.signal(t, syscall.SIGTERM)
267		p.waitExit(t, 0)
268	}
269	
270	// TestServeMetricsNanosecondAndLabelIdentity covers one-second/nanosecond
271	// coexistence and the series scoping of clashes at a distant date: samples
272	// differing by even one nanosecond coexist, while clashes stay confined to
273	// the identical label set.
274	func TestServeMetricsNanosecondAndLabelIdentity(t *testing.T) {
275		p := startServer(t, t.TempDir())
276	
277		// Two samples one nanosecond apart in the same second are both new.
278		if counts := postMetrics(t, p, `{"samples":[
279			{"id":"ns0","service":"gateway","name":"requests","at":"2026-10-01T10:00:00.111111111Z","value":1},
280			{"id":"ns1","service":"gateway","name":"requests","at":"2026-10-01T10:00:00.111111112Z","value":2}
281		]}`); counts["created"] != 2 || counts["replayed"] != 0 {
282			t.Fatalf("nanosecond-apart samples must both be new: %v", counts)
283		}
284		secondWindow := "?name=requests&service=gateway&since=2026-10-01T10:00:00Z&until=2026-10-01T10:00:01Z&step=1"
285		if count := windowSampleCount(t, p, secondWindow); count != 2 {
286			t.Fatalf("the one-second window must contain both points, got %d", count)
287		}
288	
289		// A timezone-only retry of one of them replays without adding a point.
290		if counts := postMetrics(t, p, `{"samples":[
291			{"id":"ns0","service":"gateway","name":"requests","at":"2026-10-01T18:00:00.111111111+08:00","value":1}
292		]}`); counts["created"] != 0 || counts["replayed"] != 1 {
293			t.Fatalf("timezone-only retry must replay one: %v", counts)
294		}
295		if count := windowSampleCount(t, p, secondWindow); count != 2 {
296			t.Fatalf("replay must not add a point, got %d", count)
297		}
298	
299		// Moving one id's instant by a single nanosecond conflicts.
300		postMetrics(t, p, `{"samples":[
301			{"id":"mv","service":"gateway","name":"requests","at":"2026-10-01T10:05:00.000000001Z","value":1}
302		]}`)
303		postMetricsExpectError(t, p, http.StatusConflict, `{"samples":[
304			{"id":"mv","service":"gateway","name":"requests","at":"2026-10-01T10:05:00.000000002Z","value":1}
305		]}`)
306	
307		// Different label sets are different series: both may hold the same
308		// distant instant.
309		if counts := postMetrics(t, p, `{"samples":[
310			{"id":"lp","service":"gateway","name":"requests","at":"1600-01-01T00:00:00Z","value":1,"labels":{"env":"prod"}},
311			{"id":"ls","service":"gateway","name":"requests","at":"1600-01-01T00:00:00Z","value":1,"labels":{"env":"staging"}}
312		]}`); counts["created"] != 2 || counts["replayed"] != 0 {
313			t.Fatalf("distinct label sets share an instant: %v", counts)
314		}
315		labelWindow := func(env string) string {
316			return "?name=requests&service=gateway&label=env=" + env +
317				"&since=1599-12-31T23:59:59Z&until=1600-01-01T00:00:01Z&step=2"
318		}
319		if count := windowSampleCount(t, p, labelWindow("prod")); count != 1 {
320			t.Fatalf("prod series must hold one point, got %d", count)
321		}
322		if count := windowSampleCount(t, p, labelWindow("staging")); count != 1 {
323			t.Fatalf("staging series must hold one point, got %d", count)
324		}
325		// Another id still clashes within one label series, even with an offset.
326		postMetricsExpectError(t, p, http.StatusConflict, `{"samples":[
327			{"id":"lp2","service":"gateway","name":"requests","at":"1600-01-01T08:00:00+08:00","value":2,"labels":{"env":"prod"}}
328		]}`)
329	
330		p.signal(t, syscall.SIGTERM)
331		p.waitExit(t, 0)
332	}
333	
334	func TestServeMetricsLegacyDataDirStarts(t *testing.T) {
335		// An old directory with only events.log must start and serve metrics.
336		dataDir := t.TempDir()
337		payload := []byte(`[{"id":"e1","service":"s","severity":"info","message":"m","at":"2026-10-01T09:00:00Z"}]`)
338		frame := make([]byte, 8+len(payload))
339		putFrame(frame, payload)
340		if err := os.WriteFile(filepath.Join(dataDir, "events.log"), frame, 0o644); err != nil {
341			t.Fatal(err)
342		}
343		p := startServer(t, dataDir)
344		if counts := postMetrics(t, p, `{"samples":[{"id":"m1","service":"gw","name":"requests","at":"2026-10-01T10:00:00Z","value":1}]}`); counts["created"] != 1 {
345			t.Fatalf("created=%v", counts)
346		}
347		status, got := metricAggregate(t, p,
348			"?name=requests&since=2026-10-01T10:00:00Z&until=2026-10-01T10:01:00Z&step=60")
349		if status != http.StatusOK || len(got) != 1 {
350			t.Fatalf("aggregate on legacy dir: %d %v", status, got)
351		}
352		// Events still readable.
353		if len(getEvents(t, p, "")) != 1 {
354			t.Fatal("legacy events must remain readable")
355		}
356		p.signal(t, syscall.SIGTERM)
357		p.waitExit(t, 0)
358	}
