7		"time"
8	)
9	
10	// ampEvent is a one-event batch candidate whose message is n ampersands. The
11	// save format (encoding/json) HTML-escapes '&' as the six-byte sequence
12	// '&', so a modest request body can save far larger than it arrived —
13	// the exact condition the capacity guard exists to classify.
14	func ampEvent(id string, amps int, at time.Time) Event {
15		return Event{
16			ID:       id,
17			Service:  "svc",
18			Severity: "info",
19			Message:  strings.Repeat("&", amps),
20			At:       at,
21		}
22	}
23	
24	// ampOverhead and ampWidth describe MarshalBatch's encoding of ampEvent:
25	// encoded length == overhead + width*amps. The width is measured rather than
26	// assumed so the test follows the existing save format exactly.
27	func ampEncoding(t *testing.T, at time.Time) (overhead, width int) {
28		t.Helper()
29		empty, err := MarshalBatch([]Event{ampEvent("probe", 0, at)})
30		if err != nil {
31			t.Fatalf("marshal probe: %v", err)
32		}
33		full, err := MarshalBatch([]Event{ampEvent("probe", 1000, at)})
34		if err != nil {
35			t.Fatalf("marshal wide probe: %v", err)
36		}
37		width = (len(full) - len(empty)) / 1000
38		if width <= 1 {
39			t.Fatalf("test setup: escaping must expand each '&', got width %d", width)
40		}
41		return len(empty), width
42	}
43	
44	func overheadForID(t *testing.T, id string, at time.Time) int {
45		t.Helper()
46		empty, err := MarshalBatch([]Event{ampEvent(id, 0, at)})
47		if err != nil {
48			t.Fatalf("marshal probe: %v", err)
49		}
50		return len(empty)
51	}
52	
53	// TestIngestCapacityExactLimitAccepted proves the boundary is inclusive: a
54	// batch encoding to exactly MaxBatchPayloadBytes is saved, while one extra
55	// escaped character makes it an OversizeBatchError.
56	func TestIngestCapacityExactLimitAccepted(t *testing.T) {
57		tl := NewTimeline()
58		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
59		overhead, width := ampEncoding(t, base)
60	
61		// Pad the id (one encoded byte per character) until the fixed overhead
62		// makes the limit reachable exactly with whole '&' runs.
63		id := "exact-limit"
64		for overhead%width != MaxBatchPayloadBytes%width {
65			id += "x"
66			overhead = overheadForID(t, id, base)
67		}
68		amps := (MaxBatchPayloadBytes - overhead) / width
69		if amps <= 0 {
70			t.Fatalf("test setup: overhead %d leaves no room", overhead)
71		}
72	
73		atLimit := ampEvent(id, amps, base)
74		encoded, err := MarshalBatch([]Event{atLimit})
75		if err != nil {
76			t.Fatalf("marshal: %v", err)
77		}
78		if len(encoded) != MaxBatchPayloadBytes {
79			t.Fatalf("setup: encoded %d bytes, want %d", len(encoded), MaxBatchPayloadBytes)
80		}
81	
82		committed := false
83		res, err := tl.Ingest([]Event{atLimit}, func(created []Event) error {
84			committed = true
85			return nil
86		})
87		if err != nil {
88			t.Fatalf("batch at exactly the limit must be accepted: %v", err)
89		}
90		if !committed || res.Created != 1 {
91			t.Fatalf("exact-limit batch not committed: %+v committed=%v", res, committed)
92		}
93	
94		// One more '&' pushes the saved content past the limit.
95		over := ampEvent("over-limit", amps+1, base)
96		encoded, _ = MarshalBatch([]Event{over})
97		if len(encoded) <= MaxBatchPayloadBytes {
98			t.Fatalf("setup: over batch encodes to %d", len(encoded))
99		}
100		var oversized *OversizeBatchError
101		_, err = tl.Ingest([]Event{over}, func(created []Event) error {
102			t.Fatalf("oversize batch must not reach the commit hook")
103			return nil
104		})
105		if !errors.As(err, &oversized) {
106			t.Fatalf("want OversizeBatchError, got %v", err)
107		}
108		if oversized.Size != len(encoded) || oversized.Limit != MaxBatchPayloadBytes {
109			t.Fatalf("error size=%d limit=%d, encoded=%d", oversized.Size, oversized.Limit, len(encoded))
110		}
111		if got := tl.Query(Query{}); len(got) != 1 {
112			t.Fatalf("rejected event must not be visible, got %d", len(got))
113		}
114	
115		// The rejected id stays free: the same id in a smaller later batch
116		// succeeds with no conflict and no restart.
117		small := ampEvent("over-limit", 4, base.Add(time.Second))
118		res, err = tl.Ingest([]Event{small}, nil)
119		if err != nil {
120			t.Fatalf("rejected id must remain usable: %v", err)
121		}
122		if res.Created != 1 {
123			t.Fatalf("later small batch: %+v", res)
124		}
125	}
126	
127	// TestIngestCapacityEscapingExpandsContent is the reported bug in miniature:
128	// a request whose raw content is modest saves far larger because its '&'
129	// characters are escaped in the save format. The rejection is a content
130	// error, not a storage failure.
131	func TestIngestCapacityEscapingExpandsContent(t *testing.T) {
132		tl := NewTimeline()
133		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
134		overhead, width := ampEncoding(t, base)
135		amps := (MaxBatchPayloadBytes-overhead)/width + 1
136		big := ampEvent("big", amps, base)
137	
138		if len(big.Message) >= MaxBatchPayloadBytes {
139			t.Fatalf("setup: raw message already %d bytes", len(big.Message))
140		}
141		encoded, err := MarshalBatch([]Event{big})
142		if err != nil {
143			t.Fatalf("marshal: %v", err)
144		}
145		if len(encoded) <= MaxBatchPayloadBytes {
146			t.Fatalf("setup: escaping did not expand past the limit: %d", len(encoded))
147		}
148	
149		commitCalls := 0
150		_, err = tl.Ingest([]Event{big}, func(created []Event) error {
151			commitCalls++
152			return errors.New("must not be called")
153		})
154		if !IsOversizeBatchError(err) {
155			t.Fatalf("want oversize error, got %v", err)
156		}
157		if commitCalls != 0 {
158			t.Fatalf("commit hook ran %d times", commitCalls)
159		}
160		if !strings.Contains(err.Error(), "save capacity") {
161			t.Fatalf("error must explain the save capacity, got %q", err.Error())
162		}
163		if strings.Contains(err.Error(), "restart") {
164			t.Fatalf("oversize error must not mention restart, got %q", err.Error())
165		}
166		if got := tl.Query(Query{}); len(got) != 0 {
167			t.Fatalf("nothing must be visible after rejection")
168		}
169	
170		// Storage stays usable without any restart.
171		if _, err := tl.Ingest([]Event{mkEvent("ok", "s", "info", "fine", base)}, nil); err != nil {
172			t.Fatalf("store must remain usable after oversize rejection: %v", err)
173		}
174	}
175	
176	// TestIngestCapacityOnlyNewEventsCount checks mixed replay/new batches: the
177	// save capacity measures only what would be newly written. A replay whose
178	// saved representation is huge does not count against the new events, while
179	// an oversized new event is still rejected even when accompanied by a small
180	// replay.
181	func TestIngestCapacityOnlyNewEventsCount(t *testing.T) {
182		tl := NewTimeline()
183		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
184		overhead, width := ampEncoding(t, base)
185	
186		// Seed an event whose saved form is roughly 62 MiB.
187		bigAmps := (62 << 20) / width
188		bigSaved := overhead + width*bigAmps
189		if bigSaved >= MaxBatchPayloadBytes {
190			t.Fatalf("setup: seed payload %d must fit", bigSaved)
191		}
192		big := ampEvent("big-stored", bigAmps, base)
193		if _, err := tl.Ingest([]Event{big}, nil); err != nil {
194			t.Fatalf("seed big event: %v", err)
195		}
196	
197		// A retry of the ~62 MiB event plus ~5 MiB of brand-new content encodes
198		// past the limit together; only the new content is saved, so it commits.
199		newEvent := ampEvent("new", (5<<20)/width, base.Add(time.Second))
200		newOnly, _ := MarshalBatch([]Event{newEvent})
201		if len(newOnly) >= MaxBatchPayloadBytes {
202			t.Fatalf("setup: new event alone must fit, got %d", len(newOnly))
203		}
204		combined, _ := MarshalBatch([]Event{big, newEvent})
205		if len(combined) <= MaxBatchPayloadBytes {
206			t.Fatalf("setup: combined payload %d must exceed the limit", len(combined))
207		}
208		res, err := tl.Ingest([]Event{big, newEvent}, func(created []Event) error {
209			if len(created) != 1 || created[0].ID != "new" {
210				t.Fatalf("commit hook must see only the new event, got %+v", created)
211			}
212			return nil
213		})
214		if err != nil {
215			t.Fatalf("replay must not count toward capacity: %v", err)
216		}
217		if res.Created != 1 || res.Replayed != 1 {
218			t.Fatalf("mixed batch counts: %+v", res)
219		}
220	
221		// A small replay accompanying an oversized new event cannot save it.
222		small := mkEvent("small", "s", "info", "m", base.Add(2*time.Second))
223		if _, err := tl.Ingest([]Event{small}, nil); err != nil {
224			t.Fatalf("seed small event: %v", err)
225		}
226		overAmps := (MaxBatchPayloadBytes-overhead)/width + 1
227		overNew := ampEvent("over-new", overAmps, base.Add(3*time.Second))
228		_, err = tl.Ingest([]Event{small, overNew}, func(created []Event) error {
229			t.Fatal("oversize mixed batch must not commit")
230			return nil
231		})
232		if !IsOversizeBatchError(err) {
233			t.Fatalf("want oversize error for new content, got %v", err)
234		}
235		if got := tl.Query(Query{}); len(got) != 3 {
236			t.Fatalf("rejected mixed batch must add nothing, got %d events", len(got))
237		}
238	
239		// An all-replay batch, however large its content, never saves and always
240		// reports the original created/replayed result.
241		res, err = tl.Ingest([]Event{big}, func(created []Event) error {
242			t.Fatalf("pure replay must not save, got %+v", created)
243			return nil
244		})
245		if err != nil {
246			t.Fatalf("pure replay: %v", err)
247		}
248		if res.Created != 0 || res.Replayed != 1 {
249			t.Fatalf("pure replay counts: %+v", res)
250		}
251	}
252	
253	// TestIngestCapacityChecksAfterValidationAndConflicts preserves the existing
254	// error precedence: validation failures and id conflicts are both reported
255	// ahead of the capacity check.
256	func TestIngestCapacityChecksAfterValidationAndConflicts(t *testing.T) {
257		tl := NewTimeline()
258		base := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
259		overhead, width := ampEncoding(t, base)
260		overAmps := (MaxBatchPayloadBytes-overhead)/width + 1
261	
262		seed := mkEvent("dup", "s", "info", "old", base)
263		if _, err := tl.Ingest([]Event{seed}, nil); err != nil {
264			t.Fatalf("seed: %v", err)
265		}
266	
267		// Invalid event ordered before the oversized one: validation wins.
268		invalid := mkEvent("bad", "s", "info", "   ", base.Add(time.Second))
269		_, err := tl.Ingest([]Event{invalid, ampEvent("huge", overAmps, base.Add(2*time.Second))}, nil)
270		if !IsValidationError(err) {
271			t.Fatalf("validation must precede capacity, got %v", err)
272		}
273	
274		// Conflicting id ordered before the oversized event: conflict wins.
275		conflict := mkEvent("dup", "s", "info", "different", base)
276		_, err = tl.Ingest([]Event{conflict, ampEvent("huge2", overAmps, base.Add(2*time.Second))}, nil)
277		if !IsConflictError(err) {
278			t.Fatalf("conflict must precede capacity, got %v", err)
279		}
280		if got := tl.Query(Query{}); len(got) != 1 || got[0].Message != "old" {
281			t.Fatalf("precedence rejections must not change data: %+v", got)
282		}
283	}
