565		wideFutureAt = "2184-07-20T23:34:33.709551616Z"
566		// wideFutureAltTZ is the same absolute instant as wideFutureAt written
567		// with a seven-hour-behind offset.
568		wideFutureAltTZ  = "2184-07-20T16:34:33.709551616-07:00"
569		wideOldWindow    = "?name=wide&service=gw&since=1599-12-31T23:59:59Z&until=1600-01-01T00:00:01Z&step=2"
570		wideFutureWindow = "?name=wide&service=gw&since=2184-07-20T23:34:33Z&until=2184-07-20T23:34:34Z&step=1"
