573	func TestPostMetricsWideDatePointsAccepted(t *testing.T) {
574		// These two instants are centuries apart but share one naive UnixNano
575		// value because the pre-1678 seconds overflow; both orders must ingest.
576		for _, reverse := range []bool{false, true} {
577			t.Run("order", func(t *testing.T) {
578				server := newMetricsServer(t, nil, nil)
579				body := `{"samples":[
580					{"id":"old","service":"gw","name":"wide","at":"` + wideOldAt + `","value":1},
581					{"id":"future","service":"gw","name":"wide","at":"` + wideFutureAt + `","value":2}
582				]}`
583				if reverse {
584					body = `{"samples":[
585						{"id":"future","service":"gw","name":"wide","at":"` + wideFutureAt + `","value":2},
586						{"id":"old","service":"gw","name":"wide","at":"` + wideOldAt + `","value":1}
587					]}`
588				}
589				out := postSamples(t, server, body)
590				if int(number(out["created"])) != 2 || int(number(out["replayed"])) != 0 {
591					t.Fatalf("wide pair must create two points (reverse=%v): %v", reverse, out)
592				}
593				if count := windowCount(t, server, wideOldWindow); count != 1 {
594					t.Fatalf("old-era short window must hold one point, got %d (reverse=%v)", count, reverse)
595				}
596				if count := windowCount(t, server, wideFutureWindow); count != 1 {
597					t.Fatalf("future-era short window must hold one point, got %d (reverse=%v)", count, reverse)
598				}
599	
600				// Resubmitting both with the same ids/contents replays both, even
601				// across the centuries: created stays zero and counts are unchanged.
602				out = postSamples(t, server, body)
603				if int(number(out["created"])) != 0 || int(number(out["replayed"])) != 2 {
604					t.Fatalf("identical wide batch must replay (reverse=%v): %v", reverse, out)
605				}
606				if count := windowCount(t, server, wideOldWindow); count != 1 {
607					t.Fatalf("replay changed old-era count: %d", count)
608				}
609				if count := windowCount(t, server, wideFutureWindow); count != 1 {
610					t.Fatalf("replay changed future-era count: %d", count)
611				}
612			})
613		}
614	}
