728			t.Fatalf("standalone legal sample must create one: %v", out)
729		}
730		if count := windowCount(t, server, wideFutureWindow); count != 1 {
731			t.Fatalf("future window must hold the separately ingested point, count=%d", count)
732		}
733	}
734	
735	func TestPostMetricsNanosecondApartPointsCoexist(t *testing.T) {
736		for _, reverse := range []bool{false, true} {
