738				server := newMetricsServer(t, nil, nil)
739				body := `{"samples":[
740					{"id":"n0","service":"gw","name":"wide","at":"2026-10-01T10:00:00.123456789Z","value":1},
741					{"id":"n1","service":"gw","name":"wide","at":"2026-10-01T10:00:00.123456790Z","value":2}
742				]}`
