	if out[0]["service"] != "gw" {
		t.Fatalf("service: %v", out[0]["service"])
	}
	if _, hasLabels := out[0]["labels"]; hasLabels {
		t.Fatalf("label-less series must omit labels: %v", out[0])
	}
	segments, ok := out[0]["segments"].([]any)
	if !ok || len(segments) != 2 {
